import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Criteri di similitudine fra poligoni","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fp/fphb.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fp/fphb.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fp/fphb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="criteri-di-similitudine-fra-poligoni" tabindex="-1">Criteri di similitudine fra poligoni <a class="header-anchor" href="#criteri-di-similitudine-fra-poligoni" aria-label="Permalink to “Criteri di similitudine fra poligoni”">​</a></h1><p>Siccome di solito si preferisce suddividere i poligoni in triangoli simili, i criteri, operativamente, non vengono utilizzati, sono comunque un discreto esercizio mentale: se consideriamo l&#39;equivalente dei criteri di similitudine fra triangoli scartando quello che non viene considerato:</p><p>Vediamo i vari casi.</p><p>Il primo criterio di similitudine fra triangoli dice che due triangoli sono simili se hanno due angoli congruenti (cioè manca un angolo).</p><p>Allora diremo che: <strong>il primo criterio di similitudine fra poligoni dice che due poligoni sono simili se sappiamo che tutti gli angoli sono congruenti eccetto uno e tutti i lati sono in proporzione eccetto due lati consecutivi</strong>.</p><blockquote><p>L&#39;angolo ed i lati nel senso non che sia diverso, ma che non lo sappiamo: anche quello sarà necessariamente uguale o proporzionale. Devo mettere tutti i lati in proporzione eccetto due altrimenti, se mi riferissi solamente agli angoli senza indicare i lati, tutti i rettangoli (ad esempio) sarebbero tra loro proporzionali.</p></blockquote><hr><p>Il secondo criterio di similitudine fra triangoli dice che due triangoli sono simili se hanno due lati proporzionali e congruenti gli angoli compresi fra i due lati (cioè manca un lato e due angoli).</p><p>Allora diremo che: <strong>il secondo criterio di similitudine fra poligoni dice che due poligoni sono simili se sappiamo che tutti i lati meno uno sono in proporzione e tutti gli angoli compresi fra i lati in proporzione (cioè tutti gli angoli meno due) sono congruenti</strong>.</p><blockquote><p>Nel senso non che l&#39;ultimo lato non sia in proporzione, ma che non lo sappiamo.</p></blockquote><hr><p>Il terzo criterio di similitudine fra triangoli dice che due triangoli sono simili se hanno tutti e tre i lati ordinatamente in proporzione (cioè non so che sono congruenti i tre angoli).</p><p>Allora diremo che: <strong>il terzo criterio di similitudine fra poligoni dice che due poligoni sono simili se sappiamo che tutti i lati sono ordinatamente in proporzione e tutti gli angoli, eccetto tre, sono congruenti</strong>.</p><blockquote><p>Nel senso non che i tre angoli siano diversi, ma nel senso che non lo sappiamo.</p></blockquote><hr><blockquote><p><strong>Nota:</strong> Visto l&#39;utilizzo molto raro di tali criteri saltiamo la dimostrazione (intuitivamente basta suddividere il poligono in triangoli ed applicare a ogni coppia di questi triangoli il criterio relativo partendo dai triangoli che hanno tutte le caratteristiche per applicare tali criteri).</p></blockquote>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};